//! The emoji picker, on Ctrl+. or Ctrl+; as in GTK. GNOME's chooser is part
//! of GTK's own text widgets, so other toolkits bring their own. Typing
//! searches by name; Enter or a click inserts at the composer's cursor.
use crate::{state::Desktop, theme::*};
use gpui_kit::{prelude::*, *};
use std::sync::OnceLock;

/// Unicode 17's fully qualified emoji without skin-tone variants, by group;
/// generated by `assets/emoji.py` from Unicode's emoji-test.txt.
const TABLE: &str = include_str!("../assets/emoji.txt");
const COLUMNS: usize = 9;
const CELL: f32 = 36.;
const RECENT: usize = 18;
/// The system's colour emoji font, named explicitly for emoji-only text: the
/// UI font may carry black-and-white glyphs for older emoji (DejaVu Sans has
/// the smileys), and fallback only applies to characters it lacks. (On Linux
/// this needs the patch in vendor/gpui-pre-wgpu.)
pub const FONT: &str = if cfg!(target_os = "macos") {
    "Apple Color Emoji"
} else if cfg!(windows) {
    "Segoe UI Emoji"
} else {
    "Noto Color Emoji"
};

struct Group {
    name: &'static str,
    emoji: Vec<(&'static str, &'static str)>,
}

fn groups() -> &'static [Group] {
    static GROUPS: OnceLock<Vec<Group>> = OnceLock::new();
    GROUPS.get_or_init(|| {
        let mut groups: Vec<Group> = Vec::new();
        for line in TABLE.lines() {
            if let Some(name) = line.strip_prefix('@') {
                groups.push(Group {
                    name,
                    emoji: Vec::new(),
                });
            } else if let (Some(group), Some(entry)) = (groups.last_mut(), line.split_once(' ')) {
                group.emoji.push(entry);
            }
        }
        groups
    })
}

/// Emoji whose name has a word starting with each word of `query`.
fn matches(query: &str) -> Vec<(&'static str, &'static str)> {
    let words: Vec<&str> = query.split_whitespace().collect();
    groups()
        .iter()
        .flat_map(|group| group.emoji.iter().copied())
        .filter(|(_, name)| {
            words.iter().all(|word| {
                name.split(|c: char| !c.is_alphanumeric()).any(|part| {
                    part.get(..word.len())
                        .is_some_and(|start| start.eq_ignore_ascii_case(word))
                })
            })
        })
        .collect()
}

fn name_of(emoji: &str) -> &'static str {
    groups()
        .iter()
        .flat_map(|group| group.emoji.iter())
        .find(|(candidate, _)| *candidate == emoji)
        .map_or("", |(_, name)| name)
}

/// Whether a keystroke opens the picker.
pub fn shortcut(keystroke: &Keystroke) -> bool {
    let modifiers = &keystroke.modifiers;
    modifiers.control
        && !modifiers.alt
        && !modifiers.platform
        && matches!(keystroke.key.as_str(), "." | ";")
}

/// One line of the picker: a group heading, up to `COLUMNS` emoji, or the
/// "nothing found" note. All lines are one cell high, so only the visible
/// ones are built (GPUI's uniform list).
enum Row {
    Heading(&'static str),
    Emoji(Vec<(&'static str, &'static str)>),
    Nothing,
}

/// The open picker: what is typed, and the lines it shows.
pub struct Picker {
    query: String,
    rows: Vec<Row>,
}

impl Picker {
    fn new(query: String, recent: &[&'static str]) -> Self {
        let mut rows = Vec::new();
        let add = |rows: &mut Vec<Row>, emoji: &[(&'static str, &'static str)]| {
            rows.extend(
                emoji
                    .chunks(COLUMNS)
                    .map(|chunk| Row::Emoji(chunk.to_vec())),
            );
        };
        if query.trim().is_empty() {
            if !recent.is_empty() {
                rows.push(Row::Heading("Recently used"));
                let named: Vec<_> = recent
                    .iter()
                    .map(|emoji| (*emoji, name_of(emoji)))
                    .collect();
                add(&mut rows, &named);
            }
            for group in groups() {
                rows.push(Row::Heading(group.name));
                add(&mut rows, &group.emoji);
            }
        } else {
            let found = matches(&query);
            if found.is_empty() {
                rows.push(Row::Nothing);
            }
            add(&mut rows, &found);
        }
        Self { query, rows }
    }

    /// What Enter inserts: the first emoji shown.
    fn first(&self) -> Option<&'static str> {
        self.rows.iter().find_map(|row| match row {
            Row::Emoji(emoji) => emoji.first().map(|(emoji, _)| *emoji),
            _ => None,
        })
    }
}

impl Desktop {
    pub fn open_emoji(&mut self, window: &mut Window, cx: &mut Context<Self>) {
        self.emoji = Some(Picker::new(String::new(), &self.emoji_recent));
        window.focus(&self.emoji_focus, cx);
    }

    pub fn close_emoji(&mut self, window: &mut Window, cx: &mut Context<Self>) {
        self.emoji = None;
        self.composer
            .update(cx, |input, cx| input.focus(window, cx));
    }

    fn pick_emoji(&mut self, emoji: &'static str, window: &mut Window, cx: &mut Context<Self>) {
        self.emoji_recent.retain(|recent| *recent != emoji);
        self.emoji_recent.insert(0, emoji);
        self.emoji_recent.truncate(RECENT);
        self.close_emoji(window, cx);
        self.composer
            .update(cx, |input, cx| input.insert(emoji, window, cx));
    }

    fn emoji_key(&mut self, event: &KeyDownEvent, window: &mut Window, cx: &mut Context<Self>) {
        let Some(picker) = &self.emoji else {
            return;
        };
        let keystroke = &event.keystroke;
        let modifiers = &keystroke.modifiers;
        let mut query = picker.query.clone();
        match keystroke.key.as_str() {
            "escape" => return self.close_emoji(window, cx),
            "enter" => {
                return match picker.first() {
                    Some(emoji) => self.pick_emoji(emoji, window, cx),
                    None => self.close_emoji(window, cx),
                };
            }
            "backspace" => {
                query.pop();
            }
            _ if shortcut(keystroke) => return self.close_emoji(window, cx),
            _ => match &keystroke.key_char {
                Some(text) if !modifiers.control && !modifiers.alt && !modifiers.platform => {
                    query.push_str(text);
                }
                _ => return,
            },
        }
        self.emoji = Some(Picker::new(query, &self.emoji_recent));
        cx.stop_propagation();
        cx.notify();
    }
}

fn cell(emoji: &'static str, name: &'static str, cx: &mut Context<Desktop>) -> AnyElement {
    div()
        .id(SharedString::from(emoji))
        .role(Role::Button)
        .aria_label(name)
        .size(px(CELL))
        .flex()
        .items_center()
        .justify_center()
        .rounded(px(6.))
        .font_family(FONT)
        .text_size(px(22.))
        .cursor_pointer()
        .hover(|style| style.bg(color(HOVER)))
        .tooltip(move |_, cx| cx.new(|_| crate::dialogs::Tooltip(name.into())).into())
        .on_click(cx.listener(move |this, _, window, cx| {
            this.pick_emoji(emoji, window, cx);
            cx.notify();
        }))
        .child(emoji)
        .into_any_element()
}

fn row(row: &Row, cx: &mut Context<Desktop>) -> AnyElement {
    match row {
        Row::Heading(name) => div()
            .h(px(CELL))
            .px_1()
            .pb_1()
            .flex()
            .items_end()
            .text_xs()
            .font_weight(FontWeight::SEMIBOLD)
            .text_color(color(TEXT_FAINT))
            .child(text!(id = *name, *name))
            .into_any_element(),
        Row::Emoji(emoji) => div()
            .flex()
            .children(emoji.iter().map(|(emoji, name)| cell(emoji, name, cx)))
            .into_any_element(),
        Row::Nothing => div()
            .h(px(CELL))
            .px_1()
            .flex()
            .items_center()
            .text_sm()
            .text_color(color(TEXT_MUTED))
            .child(text!("No emoji found").with_id("emoji-none"))
            .into_any_element(),
    }
}

/// The open picker above the composer; a click outside closes it.
pub fn overlay(this: &Desktop, cx: &mut Context<Desktop>) -> Option<AnyElement> {
    let picker = this.emoji.as_ref()?;
    let search = if picker.query.is_empty() {
        div()
            .text_color(color(TEXT_FAINT))
            .child(text!("Search emoji").with_id("emoji-search"))
    } else {
        div().child(text!(picker.query.clone()).with_id("emoji-search"))
    };
    let lines = uniform_list(
        "emoji-grid",
        picker.rows.len(),
        cx.processor(|this, range: std::ops::Range<usize>, _, cx| {
            let Some(picker) = &this.emoji else {
                return Vec::new();
            };
            picker.rows[range.start.min(picker.rows.len())..range.end.min(picker.rows.len())]
                .iter()
                .map(|line| row(line, cx))
                .collect()
        }),
    )
    .flex_1()
    .min_h_0()
    .px_2()
    .pb_2();
    Some(
        div()
            .id("emoji-backdrop")
            .absolute()
            .inset_0()
            .occlude()
            .on_mouse_down(
                MouseButton::Left,
                cx.listener(|this, _, window, cx| {
                    this.close_emoji(window, cx);
                    cx.notify();
                }),
            )
            .child(
                div()
                    .id("emoji-picker")
                    .role(Role::Dialog)
                    .aria_label("Emoji")
                    .track_focus(&this.emoji_focus)
                    .on_key_down(
                        cx.listener(|this, event, window, cx| this.emoji_key(event, window, cx)),
                    )
                    .on_mouse_down(MouseButton::Left, |_, _, cx| cx.stop_propagation())
                    .absolute()
                    .right(px(24.))
                    .bottom(px(78.))
                    .w(px(CELL * COLUMNS as f32 + 26.))
                    .h(px(360.))
                    .flex()
                    .flex_col()
                    .rounded(px(10.))
                    .bg(color(ELEVATED))
                    .border_1()
                    .border_color(color(BORDER_STRONG))
                    .shadow_lg()
                    .child(
                        div()
                            .m_2()
                            .px_3()
                            .py_2()
                            .rounded(px(6.))
                            .bg(color(INPUT))
                            .border_1()
                            .border_color(color(ACCENT))
                            .flex()
                            .items_center()
                            .gap_2()
                            .text_sm()
                            .child(crate::assets::icon("search", 14., color(TEXT_MUTED)))
                            .child(search),
                    )
                    .child(lines),
            )
            .into_any_element(),
    )
}

#[cfg(test)]
mod tests {
    use super::{groups, matches, name_of};

    #[test]
    fn the_table_parses_into_groups() {
        assert_eq!(groups().len(), 9);
        assert!(groups().iter().all(|group| !group.emoji.is_empty()));
        assert_eq!(name_of("😀"), "grinning face");
    }

    #[test]
    fn search_matches_word_starts() {
        assert!(matches("grin").iter().any(|(emoji, _)| *emoji == "😀"));
        assert!(matches("thumbs up").iter().any(|(emoji, _)| *emoji == "👍"));
        assert!(
            matches("GERMANY")
                .iter()
                .any(|(_, name)| *name == "flag: Germany")
        );
        assert!(matches("rinning").is_empty());
    }
}
